  1→import { useCallback, useEffect, useRef, useState } from "react";
  2→import { DropZone } from "./components/DropZone";
  3→import { Preview } from "./components/Preview";
  4→import { InspectPanel } from "./components/InspectPanel";
  5→import { CleanupPanel } from "./components/CleanupPanel";
  6→import { EditPanel } from "./components/EditPanel";
  7→import { useSvgDocument } from "./hooks/useSvgDocument";
  8→import { useInspect } from "./hooks/useInspect";
  9→import { useSelection } from "./hooks/useSelection";
 10→import { useUndoStack } from "./hooks/useUndoStack";
 11→import { detectSmallPaths } from "./utils/smallPathDetector";
 12→import { exportSvg } from "./utils/svgExport";
 13→import { flattenLayers } from "./utils/flatten";
 14→import { outlineStrokes } from "./utils/strokeToPath";
 15→
 16→function App() {
 17→  const {
 18→    containerRef,
 19→    svgElRef,
 20→    fileName,
 21→    loaded,
 22→    revision,
 23→    error,
 24→    originalSize,
 25→    loadSvg,
 26→    notifyChange,
 27→  } = useSvgDocument();
 28→
 29→  const inspect = useInspect(svgElRef, revision, originalSize);
 30→
 31→  const {
 32→    selected,
 33→    mode,
 34→    setMode,
 35→    select,
 36→    selectAll,
 37→    selectSameFill,
 38→    clearSelection,
 39→  } = useSelection(svgElRef);
 40→
 41→  const { push, undo, canUndo, remaining } = useUndoStack(notifyChange);
 42→
 43→  const fileInputRef = useRef<HTMLInputElement>(null);
 44→  const [smallThreshold] = useState(5);
 45→  const [smallPaths, setSmallPaths] = useState<SVGGraphicsElement[]>([]);
 46→
 47→  // Detect small paths when revision changes
 48→  useEffect(() => {
 49→    const svg = svgElRef.current;
 50→    if (!svg) {
 51→      setSmallPaths([]);
 52→      return;
 53→    }
 54→    const timer = setTimeout(() => {
 55→      setSmallPaths(detectSmallPaths(svg, smallThreshold));
 56→    }, 350);
 57→    return () => clearTimeout(timer);
 58→  }, [svgElRef, revision, smallThreshold]);
 59→
 60→  const handleColorChange = useCallback(
 61→    (color: string) => {
 62→      if (selected.size === 0) return;
 63→      const elements = Array.from(selected);
 64→      const previousFills = elements.map(
 65→        (el) => el.getAttribute("fill") || "",
 66→      );
 67→      push({ type: "colorChange", elements, previousFills });
 68→      for (const el of elements) {
 69→        el.setAttribute("fill", color);
 70→      }
