import type { ColorInfo } from "../hooks/useInspect";

type Props = {
  mode: SelectionMode;
  onSetMode: (mode: SelectionMode) => void;
  selectedCount: number;
  colors: ColorInfo[];
  onColorChange: (color: string) => void;
  onSelectSameFill: () => void;
