  1→import { useCallback, useEffect, useRef, useState } from "react";
  2→import type { SelectionMode } from "../hooks/useSelection";
  3→
  4→const SHAPE_TAGS = new Set([
  5→  "path",
  6→  "rect",
  7→  "circle",
  8→  "ellipse",
  9→  "line",
 10→  "polyline",
 11→  "polygon",
 12→]);
 13→
 14→const MIN_ZOOM = 0.1;
 15→const MAX_ZOOM = 20;
 16→const ZOOM_STEP = 0.1;
 17→
 18→type Props = {
 19→  containerRef: React.RefObject<HTMLDivElement | null>;
 20→  svgElRef: React.RefObject<SVGSVGElement | null>;
 21→  revision: number;
 22→  mode: SelectionMode;
 23→  onClickElement: (el: SVGElement, additive: boolean) => void;
 24→  onLassoSelect: (elements: SVGElement[]) => void;
 25→  onClearSelection: () => void;
 26→};
 27→
 28→function findShapeAncestor(el: Element): SVGElement | null {
 29→  let cur: Element | null = el;
 30→  while (cur) {
 31→    if (SHAPE_TAGS.has(cur.tagName.toLowerCase())) {
 32→      return cur as SVGElement;
 33→    }
 34→    cur = cur.parentElement;
 35→  }
 36→  return null;
 37→}
 38→
 39→export function Preview({
 40→  containerRef,
 41→  svgElRef,
 42→  revision,
 43→  mode,
 44→  onClickElement,
 45→  onLassoSelect,
 46→  onClearSelection,
 47→}: Props) {
 48→  const wrapperRef = useRef<HTMLDivElement>(null);
 49→  const lassoRef = useRef<SVGPolylineElement | null>(null);
 50→  const [lassoPoints, setLassoPoints] = useState<string>("");
 51→  const [isDrawing, setIsDrawing] = useState(false);
 52→  const pointsRef = useRef<{ x: number; y: number }[]>([]);
 53→
 54→  // Zoom & pan state
 55→  const [zoom, setZoom] = useState(1);
 56→  const [pan, setPan] = useState({ x: 0, y: 0 });
 57→  const isPanningRef = useRef(false);
 58→  const panStartRef = useRef({ x: 0, y: 0 });
 59→  const panOriginRef = useRef({ x: 0, y: 0 });
 60→  const spaceDownRef = useRef(false);
 61→
 62→  // Reset zoom/pan when SVG changes
 63→  useEffect(() => {
 64→    setZoom(1);
 65→    setPan({ x: 0, y: 0 });
 66→  }, [revision]);
 67→
 68→  const resetView = useCallback(() => {
 69→    setZoom(1);
 70→    setPan({ x: 0, y: 0 });
 71→  }, []);
 72→
 73→  // Wheel zoom (pinch on trackpad)
 74→  useEffect(() => {
 75→    const wrapper = wrapperRef.current;
 76→    if (!wrapper) return;
 77→
 78→    const handler = (e: WheelEvent) => {
 79→      e.preventDefault();
 80→
 81→      // Pinch zoom (ctrlKey) or regular wheel
 82→      const delta = e.ctrlKey ? -e.deltaY * 0.01 : -e.deltaY * 0.003;
 83→
 84→      setZoom((prev) => {
 85→        const next = Math.min(MAX_ZOOM, Math.max(MIN_ZOOM, prev * (1 + delta)));
 86→        // Adjust pan to zoom toward cursor
 87→        const rect = wrapper.getBoundingClientRect();
 88→        const cx = e.clientX - rect.left;
 89→        const cy = e.clientY - rect.top;
 90→        const scale = next / prev;
 91→        setPan((p) => ({
 92→          x: cx - scale * (cx - p.x),
 93→          y: cy - scale * (cy - p.y),
 94→        }));
 95→        return next;
 96→      });
 97→    };
 98→
 99→    wrapper.addEventListener("wheel", handler, { passive: false });
100→    return () => wrapper.removeEventListener("wheel", handler);
101→  }, []);
102→
103→  // Space key for pan mode
104→  useEffect(() => {
105→    const down = (e: KeyboardEvent) => {
106→      if (e.code === "Space" && !e.repeat) {
107→        e.preventDefault();
108→        spaceDownRef.current = true;
109→      }
110→    };
111→    const up = (e: KeyboardEvent) => {
112→      if (e.code === "Space") {
113→        spaceDownRef.current = false;
114→      }
115→    };
116→    window.addEventListener("keydown", down);
117→    window.addEventListener("keyup", up);
118→    return () => {
119→      window.removeEventListener("keydown", down);
120→      window.removeEventListener("keyup", up);
121→    };
122→  }, []);
123→
124→  const handleClick = useCallback(
125→    (e: React.MouseEvent) => {
126→      if (isPanningRef.current) return;
127→      if (mode !== "click") return;
128→      const target = e.target as Element;
129→      const shape = findShapeAncestor(target);
130→      if (shape) {
131→        onClickElement(shape, e.shiftKey);
132→      } else {
133→        onClearSelection();
134→      }
135→    },
136→    [mode, onClickElement, onClearSelection],
137→  );
138→
139→  const handleMouseDown = useCallback(
140→    (e: React.MouseEvent) => {
141→      // Middle button or space+left = pan
142→      if (e.button === 1 || (e.button === 0 && spaceDownRef.current)) {
143→        e.preventDefault();
144→        isPanningRef.current = true;
145→        panStartRef.current = { x: e.clientX, y: e.clientY };
146→        panOriginRef.current = { ...pan };
147→        return;
148→      }
149→
150→      if (mode !== "lasso" || e.button !== 0) return;
151→      setIsDrawing(true);
152→      pointsRef.current = [
153→        { x: e.nativeEvent.offsetX, y: e.nativeEvent.offsetY },
154→      ];
155→      setLassoPoints(
156→        `${e.nativeEvent.offsetX},${e.nativeEvent.offsetY}`,
157→      );
158→    },
159→    [mode, pan],
160→  );
161→
162→  const handleMouseMove = useCallback(
163→    (e: React.MouseEvent) => {
164→      if (isPanningRef.current) {
165→        const dx = e.clientX - panStartRef.current.x;
166→        const dy = e.clientY - panStartRef.current.y;
167→        setPan({
168→          x: panOriginRef.current.x + dx,
169→          y: panOriginRef.current.y + dy,
170→        });
171→        return;
172→      }
173→
174→      if (!isDrawing) return;
175→      pointsRef.current.push({
176→        x: e.nativeEvent.offsetX,
177→        y: e.nativeEvent.offsetY,
178→      });
179→      setLassoPoints(
180→        pointsRef.current.map((p) => `${p.x},${p.y}`).join(" "),
181→      );
182→    },
183→    [isDrawing],
184→  );
185→
186→  const handleMouseUp = useCallback(() => {
187→    if (isPanningRef.current) {
188→      isPanningRef.current = false;
189→      return;
190→    }
191→
192→    if (!isDrawing) return;
193→    setIsDrawing(false);
194→
195→    const svg = svgElRef.current;
196→    if (!svg || pointsRef.current.length < 3) {
197→      setLassoPoints("");
198→      return;
199→    }
200→
201→    const pts = pointsRef.current;
202→    const minX = Math.min(...pts.map((p) => p.x));
203→    const maxX = Math.max(...pts.map((p) => p.x));
204→    const minY = Math.min(...pts.map((p) => p.y));
205→    const maxY = Math.max(...pts.map((p) => p.y));
206→
207→    const container = containerRef.current;
208→    if (!container) return;
209→    const containerRect = container.getBoundingClientRect();
210→
211→    const selector = Array.from(SHAPE_TAGS).join(",");
212→    const elements = svg.querySelectorAll(selector);
213→    const selected: SVGElement[] = [];
214→
215→    for (const el of elements) {
216→      const elRect = (el as SVGElement).getBoundingClientRect();
217→      const relX = elRect.left - containerRect.left;
218→      const relY = elRect.top - containerRect.top;
219→      const relRight = relX + elRect.width;
220→      const relBottom = relY + elRect.height;
221→
222→      if (
223→        relRight >= minX &&
224→        relX <= maxX &&
225→        relBottom >= minY &&
226→        relY <= maxY
227→      ) {
228→        selected.push(el as SVGElement);
229→      }
230→    }
231→
232→    onLassoSelect(selected);
233→    setLassoPoints("");
234→    pointsRef.current = [];
235→  }, [isDrawing, svgElRef, containerRef, onLassoSelect]);
236→
237→  // Fit SVG to container whenever SVG changes
238→  useEffect(() => {
239→    const svg = svgElRef.current;
240→    if (!svg) return;
241→    svg.style.display = "block";
242→    svg.style.width = "auto";
243→    svg.style.height = "auto";
244→    svg.style.maxWidth = "100%";
245→    svg.style.maxHeight = "100%";
246→    svg.setAttribute("preserveAspectRatio", "xMidYMid meet");
247→  }, [svgElRef, revision]);
248→
249→  const zoomPercent = Math.round(zoom * 100);
250→  const cursorStyle = spaceDownRef.current || isPanningRef.current
251→    ? "grab"
252→    : mode === "lasso"
253→      ? "crosshair"
254→      : "default";
255→
256→  return (
257→    <div
258→      ref={wrapperRef}
259→      className="relative w-full h-full bg-white rounded-lg overflow-hidden"
260→      style={{ cursor: cursorStyle }}
261→    >
