import { test, expect } from "@playwright/test";
import path from "path";

const TEST_SVG = path.resolve("public/test.svg");

async function uploadSvg(page: import("@playwright/test").Page, filePath: string) {
  const fileInput = page.locator('input[type="file"][accept=".svg"]').first();
  await fileInput.setInputFiles(filePath);
}

test("debug color change", async ({ page }) => {
  page.on("console", msg => console.log("BROWSER:", msg.text()));

  await page.goto("/");
  await uploadSvg(page, TEST_SVG);

  page.on("dialog", (dialog) => dialog.accept());
  await page.getByRole("button", { name: "レイヤーを統合" }).click();
  await page.waitForTimeout(500);

  const preview = page.locator("div svg").first();
  const svgPath = preview.locator("path").first();
  await svgPath.click({ force: true });
  await page.waitForTimeout(500);

  // Check if color input exists
  const colorInputCount = await page.locator('input[type="color"]').count();
  console.log("Color inputs found:", colorInputCount);

  // Check selection count displayed
  const selText = await page.locator("text=選択中:").first().textContent();
  console.log("Selection text:", selText);

  const colorInput = page.locator('input[type="color"]');

  // Debug: add a native listener and check
  const result = await colorInput.evaluate((el: HTMLInputElement) => {
    const listeners: string[] = [];
    const origAdd = el.addEventListener.bind(el);

    // Check if value setting works
    const nativeInputValueSetter = Object.getOwnPropertyDescriptor(
      HTMLInputElement.prototype, "value",
    )!.set!;
    nativeInputValueSetter.call(el, "#ff0000");
    const valueAfterSet = el.value;

    // Track event dispatch
    let inputFired = false;
    let changeFired = false;
    el.addEventListener("input", () => { inputFired = true; }, { once: true });
    el.addEventListener("change", () => { changeFired = true; }, { once: true });

    el.dispatchEvent(new Event("input", { bubbles: true }));
    el.dispatchEvent(new Event("change", { bubbles: true }));

    return { valueAfterSet, inputFired, changeFired };
  });
  console.log("Debug result:", result);

  const newFill = await svgPath.getAttribute("fill");
  console.log("Fill after color change:", newFill);
});
