import { test, expect } from "@playwright/test";
import path from "path";

const TEST_SVG = path.resolve("public/test.svg");

async function uploadSvg(page: import("@playwright/test").Page, filePath: string) {
  const fileInput = page.locator('input[type="file"][accept=".svg"]').first();
  await fileInput.setInputFiles(filePath);
}

test("debug color change", async ({ page }) => {
  page.on("console", msg => console.log("BROWSER:", msg.text()));

  await page.goto("/");
  await uploadSvg(page, TEST_SVG);

  page.on("dialog", (dialog) => dialog.accept());
  await page.getByRole("button", { name: "レイヤーを統合" }).click();
  await page.waitForTimeout(500);

  const preview = page.locator("div svg").first();
  const svgPath = preview.locator("path").first();

  // Mark the element before clicking
  await svgPath.evaluate((el: SVGPathElement) => {
    el.setAttribute("data-test-marker", "first-path");
  });

  await svgPath.click({ force: true });
  await page.waitForTimeout(500);

  // Check if the selected element has our marker
  const markerCheck = await page.evaluate(() => {
    const selected = document.querySelectorAll('[data-svg-editor-selected]');
    const results: string[] = [];
    selected.forEach(el => {
      results.push(`selected: marker=${el.getAttribute('data-test-marker')}, fill=${el.getAttribute('fill')}`);
    });
    return results;
  });
  console.log("Marker check:", markerCheck);

  const colorInput = page.locator('input[type="color"]');
  await colorInput.evaluate((el: HTMLInputElement) => {
    const nativeInputValueSetter = Object.getOwnPropertyDescriptor(
      HTMLInputElement.prototype, "value",
    )!.set!;
    nativeInputValueSetter.call(el, "#ff0000");
    el.dispatchEvent(new Event("input", { bubbles: true }));
    el.dispatchEvent(new Event("change", { bubbles: true }));
  });

  await page.waitForTimeout(200);

  // Check fills after color change
  const afterChange = await page.evaluate(() => {
    const marked = document.querySelector('[data-test-marker="first-path"]');
    const firstPath = document.querySelector('div svg path');
    return {
      markedFill: marked?.getAttribute('fill'),
      firstPathFill: firstPath?.getAttribute('fill'),
      sameElement: marked === firstPath,
      allPathFills: Array.from(document.querySelectorAll('div svg path')).slice(0, 5).map(p => p.getAttribute('fill')),
    };
  });
  console.log("After change:", JSON.stringify(afterChange, null, 2));

  const newFill = await svgPath.getAttribute("fill");
  console.log("Locator fill:", newFill);
});

