import { test, expect } from "@playwright/test";
import path from "path";

const TEST_SVG = path.resolve("public/test.svg");

async function uploadSvg(page: import("@playwright/test").Page, filePath: string) {
  const fileInput = page.locator('input[type="file"][accept=".svg"]').first();
  await fileInput.setInputFiles(filePath);
}

test("debug click target", async ({ page }) => {
  page.on("console", msg => console.log("BROWSER:", msg.text()));

  await page.goto("/");
  await uploadSvg(page, TEST_SVG);

  page.on("dialog", (dialog) => dialog.accept());
  await page.getByRole("button", { name: "レイヤーを統合" }).click();
  await page.waitForTimeout(500);

  // Add a capture-phase listener on the document to log the click target
  await page.evaluate(() => {
    document.addEventListener("click", (e) => {
      const target = e.target as Element;
      console.log(`CLICK: target=${target.tagName}, fill=${target.getAttribute?.("fill")}, id=${target.id || "none"}`);
    }, true);
  });

  const preview = page.locator("div svg").first();
  const svgPath = preview.locator("path").first();

  // Mark each path with an index
  await page.evaluate(() => {
    const paths = document.querySelectorAll("div svg path");
    paths.forEach((p, i) => p.setAttribute("data-index", String(i)));
  });

  // Get the first path's bounding box and fill
  const firstPathInfo = await svgPath.evaluate((el: SVGPathElement) => ({
    fill: el.getAttribute("fill"),
    index: el.getAttribute("data-index"),
    bbox: el.getBoundingClientRect(),
  }));
  console.log("First path:", firstPathInfo);

  // Check what elements are at the center of the first path
  const centerElements = await page.evaluate((bbox: any) => {
    const cx = bbox.x + bbox.width / 2;
    const cy = bbox.y + bbox.height / 2;
    const elements = document.elementsFromPoint(cx, cy);
    return elements
      .filter(e => e.tagName.toLowerCase() === "path")
      .map(e => ({ fill: e.getAttribute("fill"), index: e.getAttribute("data-index") }));
  }, firstPathInfo.bbox);
  console.log("Elements at first path center:", centerElements);

  await svgPath.click({ force: true });
  await page.waitForTimeout(500);
});

