  1→import { parseSVG, makeAbsolute } from "svg-path-parser";
  2→import type { CommandMadeAbsolute } from "svg-path-parser";
  3→
  4→type Matrix = { a: number; b: number; c: number; d: number; e: number; f: number };
  5→
  6→/** Apply 2D affine transform to a point */
  7→function tp(m: Matrix, x: number, y: number): [number, number] {
  8→  return [
  9→    round(m.a * x + m.c * y + m.e),
 10→    round(m.b * x + m.d * y + m.f),
 11→  ];
 12→}
 13→
 14→function round(v: number): number {
 15→  return Math.round(v * 1000) / 1000;
 16→}
 17→
 18→/** Transform path d-attribute coordinates using matrix */
 19→function transformPathData(d: string, m: Matrix): string {
 20→  const cmds = makeAbsolute(parseSVG(d));
 21→  const parts: string[] = [];
 22→
 23→  for (const cmd of cmds) {
 24→    switch (cmd.code) {
 25→      case "M":
 26→      case "L": {
 27→        const [x, y] = tp(m, cmd.x, cmd.y);
 28→        parts.push(`${cmd.code}${x} ${y}`);
 29→        break;
 30→      }
 31→      case "H": {
 32→        // After makeAbsolute, H has x,y — treat as L
 33→        const [x, y] = tp(m, cmd.x, cmd.y);
 34→        parts.push(`L${x} ${y}`);
 35→        break;
 36→      }
 37→      case "V": {
 38→        const [x, y] = tp(m, cmd.x, cmd.y);
 39→        parts.push(`L${x} ${y}`);
 40→        break;
 41→      }
 42→      case "C": {
 43→        const [x1, y1] = tp(m, cmd.x1, cmd.y1);
 44→        const [x2, y2] = tp(m, cmd.x2, cmd.y2);
 45→        const [x, y] = tp(m, cmd.x, cmd.y);
 46→        parts.push(`C${x1} ${y1} ${x2} ${y2} ${x} ${y}`);
 47→        break;
 48→      }
 49→      case "S": {
 50→        const [x2, y2] = tp(m, cmd.x2, cmd.y2);
 51→        const [x, y] = tp(m, cmd.x, cmd.y);
 52→        parts.push(`S${x2} ${y2} ${x} ${y}`);
 53→        break;
 54→      }
 55→      case "Q": {
 56→        const [x1, y1] = tp(m, cmd.x1, cmd.y1);
 57→        const [x, y] = tp(m, cmd.x, cmd.y);
 58→        parts.push(`Q${x1} ${y1} ${x} ${y}`);
 59→        break;
 60→      }
 61→      case "T": {
 62→        const [x, y] = tp(m, cmd.x, cmd.y);
 63→        parts.push(`T${x} ${y}`);
 64→        break;
 65→      }
 66→      case "A": {
 67→        const ac = cmd as CommandMadeAbsolute & {
 68→          rx: number; ry: number; xAxisRotation: number;
 69→          largeArc: boolean; sweep: boolean;
 70→        };
 71→        // For arcs, transform endpoint + adjust radii/rotation for non-uniform scale
 72→        const [x, y] = tp(m, ac.x, ac.y);
 73→        const { rx, ry, xAxisRotation, largeArc, sweep } = transformArc(
 74→          ac.rx, ac.ry, ac.xAxisRotation, ac.largeArc, ac.sweep, m,
 75→        );
 76→        parts.push(
 77→          `A${round(rx)} ${round(ry)} ${round(xAxisRotation)} ${largeArc ? 1 : 0} ${sweep ? 1 : 0} ${x} ${y}`,
 78→        );
 79→        break;
 80→      }
 81→      case "Z": {
 82→        parts.push("Z");
 83→        break;
 84→      }
 85→    }
 86→  }
 87→
 88→  return parts.join(" ");
 89→}
 90→
 91→/** Approximate arc parameter transform for affine matrix */
 92→function transformArc(
 93→  rx: number, ry: number, rotation: number,
 94→  largeArc: boolean, sweep: boolean, m: Matrix,
 95→): { rx: number; ry: number; xAxisRotation: number; largeArc: boolean; sweep: boolean } {
 96→  // Compute scale factors from the matrix
 97→  const sx = Math.sqrt(m.a * m.a + m.b * m.b);
 98→  const sy = Math.sqrt(m.c * m.c + m.d * m.d);
 99→  // Determinant sign — if negative, the sweep direction flips
100→  const det = m.a * m.d - m.b * m.c;
101→
102→  // Rotation induced by the matrix
103→  const matRotation = Math.atan2(m.b, m.a) * (180 / Math.PI);
104→
105→  return {
106→    rx: round(rx * sx),
107→    ry: round(ry * sy),
108→    xAxisRotation: round(rotation + matRotation),
109→    largeArc,
110→    sweep: det < 0 ? !sweep : sweep,
111→  };
112→}
113→
114→/** Convert basic shapes to <path> equivalent */
115→function shapeToPathD(el: SVGElement): string | null {
116→  const tag = el.tagName.toLowerCase();
117→  const attr = (name: string) => parseFloat(el.getAttribute(name) || "0");
118→
119→  switch (tag) {
120→    case "rect": {
121→      const x = attr("x");
122→      const y = attr("y");
123→      const w = attr("width");
124→      const h = attr("height");
125→      const rx = Math.min(attr("rx") || attr("ry") || 0, w / 2);
126→      const ry = Math.min(attr("ry") || attr("rx") || 0, h / 2);
127→      if (rx === 0 && ry === 0) {
128→        return `M${x} ${y}L${x + w} ${y}L${x + w} ${y + h}L${x} ${y + h}Z`;
129→      }
