const handleClick = useCallback(
  (e: React.MouseEvent) => {
    if (isPanningRef.current) return;
    if (mode !== "click") return;
    // Shape clicks are handled by individual element handlers.
    // If the click reaches here, it means background was clicked.
    const target = e.target as Element;
    const shape = findShapeAncestor(target);
    if (!shape) {
      onClearSelection();
    }
  },
  [mode, onClearSelection],
);

const handleMouseDown = useCallback(
  (e: React.MouseEvent) => {
    // Middle button or space+left = pan
    if (e.button === 1 || (e.button === 0 && spaceDownRef.current)) {
      e.preventDefault();
      isPanningRef.current = true;
      panStartRef.current = { x: e.clientX, y: e.clientY };
      panOriginRef.current = { ...pan };
      return;
    }

    if (mode !== "lasso" || e.button !== 0) return;
    setIsDrawing(true);
    pointsRef.current = [
      { x: e.nativeEvent.offsetX, y: e.nativeEvent.offsetY },
    ];
    setLassoPoints(
      `${e.nativeEvent.offsetX},${e.nativeEvent.offsetY}`,
    );
  },
  [mode, pan],
);

const handleMouseMove = useCallback(
  (e: React.MouseEvent) => {
    if (isPanningRef.current) {
      const dx = e.clientX - panStartRef.current.x;
      const dy = e.clientY - panStartRef.current.y;
      setPan({
        x: panOriginRef.current.x + dx,
        y: panOriginRef.current.y + dy,
      });
      return;
    }

