  // so each element captures its own click regardless of visual stacking
  const onClickElementRef = useRef(onClickElement);
  onClickElementRef.current = onClickElement;
  const onClearSelectionRef = useRef(onClearSelection);
  onClearSelectionRef.current = onClearSelection;

  useEffect(() => {
    const svg = svgElRef.current;
    if (!svg) return;

    const selector = Array.from(SHAPE_TAGS).join(",");
    const shapes = svg.querySelectorAll(selector);
