        ref={containerRef}
        className="relative w-full h-full flex items-center justify-center p-4"
        style={{
          transform: `translate(${pan.x}px, ${pan.y}px) scale(${zoom})`,
          transformOrigin: "center center",
        }}
        onClick={handleClick}
        onMouseDown={handleMouseDown}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
      />
      {/* Lasso overlay */}
      {lassoPoints && (
        <svg className="absolute inset-0 w-full h-full pointer-events-none">
          <polyline
            ref={lassoRef}
            points={lassoPoints}
            fill="rgba(59, 130, 246, 0.1)"
            stroke="#3b82f6"
            strokeWidth="1"
            strokeDasharray="4"
          />
        </svg>
      )}
      {/* Zoom controls */}
      <div className="absolute bottom-3 right-3 flex items-center gap-1 bg-white/90 border border-gray-200 rounded px-1.5 py-1 text-[11px] text-gray-600 shadow-sm">
        <button
          onClick={() =>
            setZoom((z) => Math.max(MIN_ZOOM, z - ZOOM_STEP))
          }
          className="px-1 hover:text-gray-900"
          title="ズームアウト"
        >
          -
        </button>
        <button
          onClick={resetView}
          className="px-1 min-w-[3.5em] text-center hover:text-gray-900"
          title="フィットに戻す"
        >
          {zoomPercent}%
        </button>
        <button
          onClick={() =>
            setZoom((z) => Math.min(MAX_ZOOM, z + ZOOM_STEP))
          }
          className="px-1 hover:text-gray-900"
          title="ズームイン"
        >
          +
        </button>
      </div>
    </div>
  );
