      pointsRef.current.push({
        x: e.nativeEvent.offsetX,
        y: e.nativeEvent.offsetY,
      });
      setLassoPoints(
        pointsRef.current.map((p) => `${p.x},${p.y}`).join(" "),
      );
    },
    [isDrawing],
  );

  const handleMouseUp = useCallback(() => {
    if (isPanningRef.current) {
      isPanningRef.current = false;
      return;
    }

    if (!isDrawing) return;
    setIsDrawing(false);

    const svg = svgElRef.current;
    if (!svg || pointsRef.current.length < 3) {
      setLassoPoints("");
      return;
    }

    const pts = pointsRef.current;
    const minX = Math.min(...pts.map((p) => p.x));
    const maxX = Math.max(...pts.map((p) => p.x));
    const minY = Math.min(...pts.map((p) => p.y));
    const maxY = Math.max(...pts.map((p) => p.y));

    const container = containerRef.current;
    if (!container) return;
    const containerRect = container.getBoundingClientRect();

    const selector = Array.from(SHAPE_TAGS).join(",");
    const elements = svg.querySelectorAll(selector);
    const selected: SVGElement[] = [];

    for (const el of elements) {
      const elRect = (el as SVGElement).getBoundingClientRect();
      const relX = elRect.left - containerRect.left;
      const relY = elRect.top - containerRect.top;
      const relRight = relX + elRect.width;
      const relBottom = relY + elRect.height;

      if (
        relRight >= minX &&
        relX <= maxX &&
        relBottom >= minY &&
        relY <= maxY
      ) {
        selected.push(el as SVGElement);
      }
    }

    onLassoSelect(selected);
    setLassoPoints("");
    pointsRef.current = [];
  }, [isDrawing, svgElRef, containerRef, onLassoSelect]);

  // Attach click handlers directly on SVG shape elements
  // so each element captures its own click regardless of visual stacking
  const onClickElementRef = useRef(onClickElement);
  onClickElementRef.current = onClickElement;
  const onClearSelectionRef = useRef(onClearSelection);
  onClearSelectionRef.current = onClearSelection;

  useEffect(() => {
    const svg = svgElRef.current;
    if (!svg) return;

    const selector = Array.from(SHAPE_TAGS).join(",");
    const shapes = svg.querySelectorAll(selector);
    const controller = new AbortController();

